const items = $input.all();
const out = [];
for (let idx = 0; idx < items.length; idx++) {
  const row = items[idx].json || {};
  if (!row.event_key || !row.lead_key) continue;
  let payload = {};
  try {
    payload = row.payload_json ? JSON.parse(String(row.payload_json)) : {};
  } catch (e) {
    payload = {};
  }
  const curCount = Number(row.retry_count || 0);
  const maxRetries = Number(row.max_retries || 3);
  const nextCount = curCount + 1;
  out.push({
    json: {
      dlq_event_key: String(row.event_key),
      dlq_lead_key: String(row.lead_key),
      next_retry_count: nextCount,
      max_retries: maxRetries,
      is_eligible: curCount < maxRetries,
      lead_key: String(payload.lead_key || row.lead_key),
      source: String(payload.source || "dlq_retry"),
      name: String(payload.name || "Unknown Prospect"),
      email: String(payload.email || ""),
      phone: String(payload.phone || ""),
      company: String(payload.company || "Unspecified"),
      inquiry_text: String(payload.inquiry_text || "Follow-up requested"),
      requested_slot: String(payload.requested_slot || ""),
      is_retry: true,
      retry_count: nextCount,
      simulate_primary_failure: false,
      simulate_all_ai_failure: false
    },
    pairedItem: { item: idx }
  });
}
return out;

const batchCtx = $("Loop Pending Retries").item.json || {};
const subOut = $("Re-Run Workflow 01 Intake").item.json || {};
const vaultRow = $input.first().json || {};
const st = String(vaultRow.status || subOut.status || "");
const recovered = (st === "QUEUED_FOR_APPROVAL" || st === "DISPATCHED" || st === "HELD") && !subOut.error;
const exhausted = !recovered && Number(batchCtx.next_retry_count || 1) >= Number(batchCtx.max_retries || 3);
const outcome = recovered ? "RECOVERED" : (exhausted ? "PERMANENT_FAIL" : "RETRY_LATER");
return [{
  json: {
    outcome,
    dlq_event_key: String(batchCtx.dlq_event_key || ""),
    lead_key: String(batchCtx.dlq_lead_key || ""),
    next_retry_count: Number(batchCtx.next_retry_count || 1),
    max_retries: Number(batchCtx.max_retries || 3),
    vault_status: st || "UNKNOWN",
    ai_provider: String(vaultRow.ai_provider || "none"),
    error_detail: subOut.error ? String(subOut.error.message || JSON.stringify(subOut.error)) : "AI triage remained unavailable",
    now_iso: new Date().toISOString()
  },
  pairedItem: { item: 0 }
}];

const leads = $("Fetch All Vault Leads").all().map(i => i.json).filter(r => r && r.lead_key);
const retries = $("Fetch All DLQ Entries").all().map(i => i.json).filter(r => r && r.event_key);
const bookings = $("Fetch All Confirmed Bookings").all().map(i => i.json).filter(r => r && r.booking_id);
const audits = $("Fetch Recent Audit Log").all().map(i => i.json).filter(r => r && r.event_code);
const total_leads = leads.length;
const dropped_leads = 0;
let pending_approvals = 0;
let dispatched_count = 0;
let held_count = 0;
let manual_review_count = 0;
let conflict_count = 0;
let critical_count = 0;
let gemini_count = 0;
let openrouter_count = 0;
const pending_items = [];
for (const l of leads) {
  const st = String(l.status || "");
  if (st === "QUEUED_FOR_APPROVAL") {
    pending_approvals++;
    if (pending_items.length < 5) pending_items.push({ lead_key: l.lead_key, name: l.name, company: l.company, lead_score: Number(l.lead_score || 0), urgency: l.urgency || "NORMAL" });
  }
  else if (st === "DISPATCHED") dispatched_count++;
  else if (st === "HELD") held_count++;
  else if (st === "MANUAL_REVIEW") manual_review_count++;
  else if (st === "SLOT_CONFLICT") conflict_count++;
  if (String(l.urgency || "") === "CRITICAL") critical_count++;
  if (String(l.ai_provider || "") === "gemini_pro_plus") gemini_count++;
  else if (String(l.ai_provider || "") === "openrouter_fallback") openrouter_count++;
}
const dlq_pending = retries.filter(r => r.status === "PENDING_RETRY").length;
const dlq_recovered = retries.filter(r => r.status === "RECOVERED").length;
const dlq_perm_fail = retries.filter(r => r.status === "PERMANENT_FAIL").length;
const fallback_events = audits.filter(a => a.event_type === "AI_FALLBACK_RECOVERED" || a.event_type === "DLQ_RETRY_RECOVERED").length;
const security_blocks = audits.filter(a => a.event_type === "INVALID_APPROVAL_TOKEN" || a.event_type === "BOOKING_SLOT_CONFLICT").length;
const confirmed_bookings = bookings.filter(b => b.status === "CONFIRMED").length;
const recovery_rate_pct = total_leads > 0 ? Math.round(((total_leads - dlq_perm_fail) / total_leads) * 1000) / 10 : 100;
const date_label = new Date().toLocaleDateString("en-US", { timeZone: "Asia/Manila", year: "numeric", month: "short", day: "numeric" });
const kpis = { total_leads, dropped_leads, pending_approvals, dispatched_count, held_count, manual_review_count, conflict_count, critical_count, gemini_count, openrouter_count, dlq_pending, dlq_recovered, dlq_perm_fail, fallback_events, security_blocks, confirmed_bookings, recovery_rate_pct };
const deterministic_summary = "Zero-Leak Vault holds " + total_leads + " total inquiries with 0 dropped leads (" + recovery_rate_pct + "% health). Today has " + pending_approvals + " pending approval(s), " + dispatched_count + " dispatched, " + confirmed_bookings + " confirmed booking(s), and " + fallback_events + " automatic recovery event(s).";
const prompt_payload = JSON.stringify({ date: date_label, kpis, pending_preview: pending_items });
return [{ json: { date_label, kpis, pending_items, deterministic_summary, prompt_payload, audit_total_events: audits.length }, pairedItem: { item: 0 } }];

