function escHtml(s) {
  return String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
const ctx = $("Compute Executive KPIs").first().json;
const k = ctx.kpis;
const incoming = $input.first().json || {};
let executive_narrative = String(incoming.text || "").trim();
let narrative_provider = String(incoming.narrative_provider || "gemini_pro_plus");
if (!executive_narrative) {
  executive_narrative = ctx.deterministic_summary;
  narrative_provider = "deterministic_fallback";
}
let pendingRowsHtml = "<p style=\"color:#475569;margin:0;\">No pending approvals in queue.</p>";
if (ctx.pending_items && ctx.pending_items.length > 0) {
  pendingRowsHtml = "<ul style=\"margin:8px 0 0 0;padding-left:18px;\">" +
    ctx.pending_items.map(p => "<li><strong>" + escHtml(p.lead_key) + "</strong> — " + escHtml(p.name) + " (" + escHtml(p.company) + ") · Score " + p.lead_score + "/100 · " + escHtml(p.urgency) + "</li>").join("") +
    "</ul>";
}
const email_subject = "[YourCompany 7:30 AM Brief] " + ctx.date_label + " · " + k.total_leads + " Preserved / 0 Dropped";
const email_html = "<div style=\"font-family:Inter,Segoe UI,Arial,sans-serif;max-width:660px;margin:0 auto;color:#0f172a;line-height:1.55;\">" +
  "<h2 style=\"margin-bottom:4px;\">Zero-Leak Executive Guardrail — Morning Executive Brief</h2>" +
  "<p style=\"margin-top:0;color:#64748b;font-size:13px;\">" + escHtml(ctx.date_label) + " (Asia/Manila) · Narrative AI: " + escHtml(narrative_provider) + "</p>" +
  "<div style=\"background:#f8fafc;border-left:4px solid #10b981;padding:12px 16px;border-radius:6px;margin:16px 0;\"><strong>Executive Summary:</strong><br>" + escHtml(executive_narrative) + "</div>" +
  "<table style=\"width:100%;border-collapse:collapse;font-size:14px;margin-bottom:16px;\">" +
  "<tr><td style=\"padding:8px;border:1px solid #e2e8f0;\"><strong>Total Preserved Leads</strong></td><td style=\"padding:8px;border:1px solid #e2e8f0;\">" + k.total_leads + " (Dropped: " + k.dropped_leads + ")</td></tr>" +
  "<tr><td style=\"padding:8px;border:1px solid #e2e8f0;\"><strong>Pending Executive Approvals</strong></td><td style=\"padding:8px;border:1px solid #e2e8f0;\">" + k.pending_approvals + "</td></tr>" +
  "<tr><td style=\"padding:8px;border:1px solid #e2e8f0;\"><strong>Dispatched / Held / Manual Review</strong></td><td style=\"padding:8px;border:1px solid #e2e8f0;\">" + k.dispatched_count + " / " + k.held_count + " / " + k.manual_review_count + "</td></tr>" +
  "<tr><td style=\"padding:8px;border:1px solid #e2e8f0;\"><strong>Confirmed Bookings / Conflicts Blocked</strong></td><td style=\"padding:8px;border:1px solid #e2e8f0;\">" + k.confirmed_bookings + " / " + k.conflict_count + "</td></tr>" +
  "<tr><td style=\"padding:8px;border:1px solid #e2e8f0;\"><strong>Auto-Recovered (Fallback + DLQ)</strong></td><td style=\"padding:8px;border:1px solid #e2e8f0;\">" + k.fallback_events + " (DLQ Recovered: " + k.dlq_recovered + ", Pending: " + k.dlq_pending + ")</td></tr>" +
  "<tr><td style=\"padding:8px;border:1px solid #e2e8f0;\"><strong>Security / Conflict Guardrail Triggers</strong></td><td style=\"padding:8px;border:1px solid #e2e8f0;\">" + k.security_blocks + "</td></tr>" +
  "</table>" +
  "<h3 style=\"font-size:15px;margin-bottom:6px;\">Top Pending Approvals</h3>" + pendingRowsHtml + "</div>";
const slack_message = ":sunrise_over_mountains: *Zero-Leak Executive Guardrail 7:30 AM Brief* (" + ctx.date_label + ")\n" +
  "*Executive Note (" + narrative_provider + "):* " + executive_narrative + "\n" +
  "*Leads:* " + k.total_leads + " total · *0 dropped* · *Pending:* " + k.pending_approvals + " · *Dispatched:* " + k.dispatched_count + " · *Held:* " + k.held_count + "\n" +
  "*Resilience:* " + k.fallback_events + " auto-recoveries · " + k.confirmed_bookings + " bookings · " + k.security_blocks + " guardrail blocks";
return [{
  json: {
    date_label: ctx.date_label,
    narrative_provider,
    executive_narrative,
    kpis: k,
    email_subject,
    email_html,
    slack_message,
    audit_code: "ZL-BRIEF-" + Date.now(),
    now_iso: new Date().toISOString()
  },
  pairedItem: { item: 0 }
}];
